NUM = re.compile(r"\d[\d,]*(?:\.\d+)?")


def nums(text: str) -> set:
    return {m.replace(",", "") for m in NUM.findall(text)}


def english_text(e):
    parts = [e["title"], e["summary"], e["quickTake"]] + [s["heading"] + " " + s["body"] for s in e["sections"]]
    for st in e["stats"]:
        parts += [st["metric_label_en"], st["before_label_en"], st["before_value_en"], st["after_label_en"], st["after_value_en"]]
    return " ".join(parts)


def build(slug, loc):
    t = T[slug][loc]
    e = EN[slug]
    title, summary, quick, sections, stats = t
    if len(sections) != len(e["sections"]) or len(stats) != len(e["stats"]):
        raise SystemExit(f"{slug}/{loc}: structure mismatch")
    payload = {
        "entrySlug": slug, "locale": loc, "title": title, "summary": summary, "quickTake": quick,
        "bodySections": [{"heading": h, "body": b} for h, b in sections],
        "stats": [{"statKey": e["stats"][i]["stat_key"], "metricLabel": s[0], "beforeLabel": s[1], "beforeValue": s[2], "afterLabel": s[3], "afterValue": s[4]} for i, s in enumerate(stats)],
        "note": NOTE,
    }
    tr_text = " ".join([title, summary, quick] + [h + " " + b for h, b in sections] + [" ".join(s) for s in stats])
    missing = nums(english_text(e)) - nums(tr_text)
    return payload, missing


def main(submit):
    secret = None
    if submit:
        for line in Path(__file__).resolve().parents[2] / ".env.local".read_text(encoding="utf-8").splitlines():
            if line.startswith("CRON_SECRET="):
                secret = line.split("=", 1)[1].strip().strip('"')
    bad = 0
    for slug in T:
        for loc in ("bn", "te", "mr"):
            payload, missing = build(slug, loc)
            status = "numbers ok" if not missing else f"MISSING NUMBERS {sorted(missing)}"
            if missing:
                bad += 1
            line = f"{slug[:34]:34} {loc} {status}"
            if submit and not missing:
                req = urllib.request.Request("https://modinekiyakyahai.com/api/pipeline/translation-ingest", data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
                                             headers={"Authorization": f"Bearer {secret}", "Content-Type": "application/json"}, method="POST")
                try:
                    with urllib.request.urlopen(req, timeout=60) as r:
                        line += f"  -> {r.status} {r.read().decode()[:80]}"
                except urllib.error.HTTPError as ex:
                    line += f"  -> HTTP {ex.code} {ex.read().decode()[:300]}"
            print(line)
    if bad:
        sys.exit(1)


if __name__ == "__main__":
    main("--submit" in sys.argv)
